from __future__ import annotations

import logging
import os
import pathlib
import re
from collections import defaultdict
from unittest.mock import MagicMock

from taf.config.testline import TestLine  # type: ignore
from taf.config.testline.airscale import CommonUnit  # type: ignore
from taf.config.testline.enb import RealEnb  # type: ignore
from taf.config.testline.gnb import CU, DU, ClassicalBts, CloudBts  # type: ignore
from taf.config.testline.gnb.networkaddress import NetworkAddress  # type: ignore
from taf.config.testline.testpc import Connection  # type: ignore
from taf.config.testline.ue import CUS, IPHY, Airphone, Simulator  # type: ignore

from taf.ul.ue.sim.env_setup.utils.config_validators import convert_sim_type_to_enum
from taf.ul.ue.sim.env_setup.utils.enums import DevicesNames

try:
    from importlib.util import module_from_spec, spec_from_file_location
except ImportError:
    pass


UTE_USER = "/home/ute/"
GERRIT_PATH = pathlib.Path(UTE_USER, "testline_configuration")


def get_ute_tl_config(logger: logging.Logger | MagicMock = MagicMock()) -> tuple[TestLine, dict]:
    """
    Fetch testline configuration base on testline location and name.

    :raise: ValueError
    :return: UTE testline configuration as 'kind of' dict
    :rtype: ute_testline_configuration.ute_config.UTE_CONFIG
    """
    tl_name = get_tl_name()
    module_path = get_config_module_path(logger, tl_name)
    config = load_tl_config(tl_name, module_path)
    return config.tl, config.tl.tl_config if hasattr(config.tl, "tl_config") else {}


def load_tl_config(tl_name, module_path):
    spec = spec_from_file_location(tl_name, module_path)
    config = module_from_spec(spec)  # type: ignore
    spec.loader.exec_module(config)  # type: ignore
    return config


def get_config_module_path(logger, tl_name):
    module_path = GERRIT_PATH / tl_name / "__init__.py"
    if not module_path.exists():
        raise Exception(f"Config doesn't exists! {module_path}")
    logger.info(f"Configuration path detected: {module_path}")
    return module_path.as_posix()


def get_tl_name() -> str:
    """
    Return testline name.

    :raise: AttributeError
    :return: testline name
    :rtype: str
    """
    vars_to_look_for_tl_name = {
        _get_env_variable("SESSION_MANAGER"): re.compile("local/(.*?):"),
        os.uname()[1]: re.compile("(.*)"),
    }
    for var_value, var_re in list(vars_to_look_for_tl_name.items()):
        if var_value:
            tl_name = match.group(1) if (match := var_re.search(var_value)) else "UNKNOWN"
            tl_name = _parse_tl_name(tl_name)
            return tl_name
    else:
        raise AttributeError("Could not get testline name")


def _get_env_variable(env_name: str) -> str:
    """
    Return value od env. variable as string.

    :param env_name:
    :type env_name:
    :return: value of env. variable or empty string
    :rtype: str
    """
    try:
        return os.environ[env_name]
    except KeyError:
        return ""


def _parse_tl_name(tl_name: str) -> str:
    """
    Parese testline name to fulfill naminig conventions.

    :param tl_name: testline name
    :type tl_name: str
    :return: parsed testlien name
    :rtype: str
    """
    not_single_testline = re.search(r"-\d+$", tl_name)  # name end with number
    if not_single_testline:
        tl_name = tl_name[: not_single_testline.start()]
    tl_name = tl_name.replace("-", "_")
    return tl_name


def prepare_config_for_tl(tl_config):
    return _prepare_config_for_taf_tl(tl_config)


def _prepare_config_for_taf_tl(tl_config):
    if _has_connections(tl_config):
        return _prepare_config_for_taf_tl_with_connections(tl_config)

    bts_type, other_bts = (DevicesNames.ENB, DevicesNames.GNB) if tl_config.enbs else (DevicesNames.GNB, DevicesNames.ENB)
    btses_config = tl_config.enbs or tl_config.gnbs
    bts_count = len(btses_config)
    sim_conf = tl_config.ues

    host_count = len(tl_config.test_pcs)
    bts_per_host = int(bts_count // host_count)
    sim_per_fsm = int(len(sim_conf) // bts_count)
    new_conf = {}
    for host_id in range(host_count):
        btses = [btses_config[(bts_per_host * host_id) + i] for i in range(bts_per_host)]
        sims_dict = defaultdict(list)
        for sim in (sim_conf[(bts_per_host * host_id) + i] for i in range(sim_per_fsm)):
            sims_dict[convert_sim_type_to_enum(type(sim).__name__)].append(sim)
        new_conf.update({host_id + 1: {bts_type: btses, other_bts: [], "host": tl_config.test_pcs[host_id], **sims_dict}})
    return new_conf


def _get_device_type(device):
    if isinstance(device, RealEnb):
        return DevicesNames.ENB
    elif isinstance(device, ClassicalBts) or isinstance(device, CU) or isinstance(device, DU):
        return DevicesNames.GNB
    elif isinstance(device, CloudBts):
        return DevicesNames.CLOUD_BTS
    elif isinstance(device, CUS):
        return DevicesNames.CUS
    elif isinstance(device, IPHY):
        return DevicesNames.IPHY
    elif isinstance(device, Airphone):
        return DevicesNames.AIRPHONE
    elif isinstance(device, Simulator):
        return DevicesNames.SIMULATOR
    return None


def _prepare_config_for_taf_tl_with_connections(tl_config):
    new_conf = {}
    for idx, test_pc in enumerate(tl_config.test_pcs, start=1):
        new_conf[idx] = {"host": test_pc}
        devices = defaultdict(list)
        for connection in test_pc.connections:
            if isinstance(connection, NetworkAddress):
                continue
            dev = _get_device_for_connection(tl_config, connection)
            dev_type = _get_device_type(dev)
            if dev_type:
                devices[dev_type].append(dev)
        new_conf[idx] = {"host": test_pc, **devices}
    return new_conf


def _has_connections(tl_config):
    for test_pc in tl_config.test_pcs:
        if not hasattr(test_pc, "connections"):
            return False
        if not test_pc.connections:
            return False
    return True


def _get_system_common_units(sys_dev):
    if hasattr(sys_dev, "system_module") and sys_dev.system_module and sys_dev.system_module.common_units:
        return sys_dev.system_module.common_units
    elif hasattr(sys_dev, "airscale") and sys_dev.airscale and sys_dev.airscale.common_units:
        return sys_dev.airscale.common_units
    elif hasattr(sys_dev, "dus") and sys_dev.dus:
        ret: list = []
        for du in sys_dev.dus:
            ret = ret + _get_system_common_units(du)
        return ret
    elif hasattr(sys_dev, "l1") and sys_dev.l1 and hasattr(sys_dev.l1, "common_units") and sys_dev.l1.common_units:
        return sys_dev.l1.common_units
    return []


def _get_device_for_connection(tl_config, connection):
    comm_unit = None
    if isinstance(connection, Connection):
        comm_unit = connection.device
    elif isinstance(connection, CommonUnit):
        comm_unit = connection

    if comm_unit:
        if hasattr(tl_config, "enbs") and tl_config.enbs:
            for enb in tl_config.enbs:
                if enb is comm_unit:
                    return enb
                comm_units = _get_system_common_units(enb)
                if any(comm_unit is unit for unit in comm_units):
                    return enb
        if hasattr(tl_config, "ues") and tl_config.ues:
            for ue in tl_config.ues:
                if ue is comm_unit:
                    return ue
                comm_units = _get_system_common_units(ue)
                if any(comm_unit is unit for unit in comm_units):
                    return ue
        if hasattr(tl_config, "gnbs") and tl_config.gnbs:
            for gnb in tl_config.gnbs:
                for du in gnb.dus:
                    comm_units = _get_system_common_units(du)
                    if any(comm_unit is unit for unit in comm_units):
                        return gnb
    else:
        return connection
    return None
